CREATE FUNCTION public.can_access_applicant_file(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin_or_manager(auth.uid()) AND public.has_workspace_access(auth.uid(),'recruitment') AND EXISTS(SELECT 1 FROM public.applicants a WHERE a.id::text=split_part(_path,'/',1) AND a.org_id=public.current_org_id()) $$; REVOKE ALL ON FUNCTION public.can_access_applicant_file(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_access_applicant_file(text) TO authenticated; CREATE POLICY applicant_company_file_gate ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING(bucket_id<>'applicant-docs' OR public.can_access_applicant_file(name)) WITH CHECK(bucket_id<>'applicant-docs' OR public.can_access_applicant_file(name));